def skill_files(root: Path, skip: set[str] = frozenset()) -> list[Path]:
    if not root.is_dir():
        return []
    found = []
    for dirpath, dirnames, filenames in os.walk(root, followlinks=True):
        dirnames[:] = [d for d in dirnames if d not in (".git", "node_modules") and d not in skip]
        if "SKILL.md" in filenames:
            found.append(Path(dirpath) / "SKILL.md")
    return found


def record(path: Path, prefix: str | None) -> dict | None:
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None
    fields, body = parse_frontmatter(text)
    bare = (fields.get("name") or path.parent.name).strip()
    description = " ".join((fields.get("description") or "").split())
    if not bare or not description:
        return None
    return build(
        f"{prefix}:{bare}" if prefix else bare,
        description,
        " ".join(body.split())[:BODY_EXCERPT],
        str(path),
    )


def build(name: str, description: str, body: str, source: str) -> dict:
    # The index line Jev ranks on in request 1, kept short on purpose: every skill
    # shares one request's state budget and context rot is the documented failure.
    short = description if len(description) <= 200 else description[:197] + "..."
    return {
        "name": name,
        "description": short,
        "description_full": description,
        "body": body,
        "source": source,
    }


def collect() -> tuple[dict[str, dict], list[str]]:
    flags = enabled_plugins()
    skills: dict[str, dict] = {}
    skipped: list[str] = []

    # Personal skills. `synced` under here is a managed bucket, handled separately.
    for path in skill_files(CLAUDE / "skills", skip={"synced"}):
        entry = record(path, None)
        if entry:
            skills.setdefault(entry["name"], entry)

    synced_skills = CLAUDE / "skills" / "synced"
    if synced_skills.is_dir():
        for bucket in sorted(p for p in synced_skills.iterdir() if p.is_dir()):
            for path in skill_files(bucket):
                entry = record(path, SYNCED_SKILLS_PLUGIN)
                if entry:
                    skills.setdefault(entry["name"], entry)

    plugins_root = CLAUDE / "plugins"
    for container, honour_flags in (("cache", True), ("synced", False)):
        base = plugins_root / container
        if not base.is_dir():
            continue
        for middle in sorted(p for p in base.iterdir() if p.is_dir()):
            marketplace = middle.name
            for plugin_dir in sorted(p for p in middle.iterdir() if p.is_dir()):
                plugin = plugin_dir.name
                if honour_flags and flags.get((plugin, marketplace)) is False:
                    skipped.append(f"{plugin}@{marketplace}")
                    continue
                for path in skill_files(plugin_dir):
                    entry = record(path, plugin)
                    if entry:
                        skills.setdefault(entry["name"], entry)

    if SUPPLEMENTAL_PATH.exists():
        try:
            extra = json.loads(SUPPLEMENTAL_PATH.read_text(encoding="utf-8"))
        except ValueError:
            extra = {}
        for item in extra.get("skills", []):
            name, description = item.get("name"), item.get("description")
            if name and description:
                skills.setdefault(
                    name,
                    build(name, description, item.get("body", ""), "supplemental.json"),
                )

    return skills, sorted(set(skipped))


def allow_list() -> set[str] | None:
    if not EXPECTED_PATH.exists():
        return None
    return {
        line.strip()
        for line in EXPECTED_PATH.read_text(encoding="utf-8").splitlines()
        if line.strip() and not line.startswith("#")
    }

